import {makeRack} from './war-rack-core.js';import {measureAudio} from './audio-certification.js';
const specs=[['Lead Vocal',75,2],['Backing Vocal',100,2],['Adlibs',110,2],['Baby Voice',105,2],['Guitar',70,1.6],['Bass',25,1.7],['808',20,1.3],['Keys',45,1.5],['Synth',35,1.5],['Strings',60,1.5],['Wind',70,1.5],['Drums',25,1.4],['Percussion',60,1.5],['Log Drum',20,1.3],['Other',30,1.5]];
export const PREMIX_RACKS=specs.map(([source,highpass,ratio],i)=>makeRack('premix-'+i,'PREMIX / '+source,'Tous',source,'premix',[['sculpt',{highpass,cutoff:20000}],['glue',{threshold:-18,ratio,attack:30,release:180,makeup:0,mix:.65}]],'Starting correction; check source and gain before processing.'));
export function suggestHeadroom(buffer,target=-12){if(!Number.isFinite(target)||target> -1||target< -36)throw Error('Cible invalide');const m=measureAudio(buffer);if(m.invalid||m.clipped||!Number.isFinite(m.peakDb))return {status:'review-source',gainDb:null,peakDb:Number.isFinite(m.peakDb)?m.peakDb:null};return {status:'measured',gainDb:Math.min(0,target-m.peakDb),peakDb:m.peakDb,target};}
